await story('A8-03-other-department',async()=>{const o=await context(cases[0]);await signIn(o.p,'outsider');await o.p.locator('[data-welcome=no-actions]').waitFor();await o.p.goto(roomUrl);await o.p.locator('.hub-chat').waitFor();await shot(o.p,'A8-03-other-department-stale-room');check('no protected answer shown to outsider',await o.p.getByText('Recorded acceptance answer',{exact:true}).count()===0);check('no extra representative input',deliveries.length===1);receipt.outsiderRoomText=await o.p.locator('body').innerText();await o.ctx.close();});
await story('A8-05-grant-boundary',async()=>{const o=await context(cases[0]);await signIn(o.p,'ungranted');await o.p.locator('[data-entry=chat] button').click();await o.p.locator('.hub-pick').waitFor();await shot(o.p,'A8-05-ungranted-picker');check('same department without grant sees zero agents',await o.p.locator('.hub-pick-row').count()===0);await o.ctx.close();});
await story('A8-12-negative-restore-resume',async()=>{
 const before=deliveries.length;person('asker').groups=[GROUP_C];await asker.p.fill('#msgIn','Complete negative must not deliver');await click(asker.p,'#sendBtn','Send after group removal');await asker.p.locator('.hub-dock .err, .hub-banner').first().waitFor();await shot(asker.p,'A8-12-complete-negative');check('negative group causes no new input',deliveries.length===before);
 await admin.p.reload();await admin.p.locator(`[data-paused="${person('asker').id}"]`).waitFor();await shot(admin.p,'A8-12-paused-asker');person('asker').groups=['bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'];await asker.p.reload();await asker.p.locator('#msgIn').waitFor();await asker.p.fill('#msgIn','Rejoining alone must not resume');await click(asker.p,'#sendBtn','Retry after group restore before Resume');await asker.p.locator('.hub-dock .err, .hub-banner').first().waitFor();check('rejoin does not deliver before Resume',deliveries.length===before);await shot(asker.p,'A8-12-restored-still-paused');
 await admin.p.locator(`[data-paused="${person('asker').id}"] button`).click();await admin.p.locator(`[data-paused="${person('asker').id}"]`).waitFor({state:'detached'});await asker.p.reload();await asker.p.locator('#msgIn').waitFor();await asker.p.fill('#msgIn','Explicitly resumed Department A question');await click(asker.p,'#sendBtn','Send after explicit Resume');await waitFor(()=>deliveries.length===before+1,'resumed input reaches representative');await new Promise(r=>setTimeout(r,200));receipt.resumeAnswer=await reportHook({correlationId:deliveries.at(-1).correlationId,caller:'general',text:'Resumed acceptance answer',callerCurrent:()=>memberLive});await asker.p.getByText('Resumed acceptance answer',{exact:true}).waitFor();await shot(asker.p,'A8-12-resumed-answer');
});
